import{_ as s,O as a,o as i,c as n,a as o,i as r,f as c}from"./chunks/framework.fmIt2z2h.js";const h=JSON.parse('{"title":"D.25　教育、知识生产、专业与终身学习","description":"","frontmatter":{"title":"D.25　教育、知识生产、专业与终身学习","xkChars":816,"xkLessons":{"D.25":{"title":"D.25　教育、知识生产、专业与终身学习","lead":"学到了什么、拿到什么资格和获得什么机会是不同结果；更正要追到实际下游决定及其时间窗口。","explanation":["原文定位：第4917—4934行，原站定位/theory/appendix-d/d-25#section-d-25。本题切片及完整用户原稿均在source目录，可逐字回查。","短引文：“考试能够测量某种知识，也不因此证明机会公平”。教育目的、可进入的学习、实际技能、测验解释、资格与后续机会分别取证。不能因为考试有测量效用就关闭公平问题，也不能因机会不公平就断言无人真正学会东西。[T-main]","专业讲授和共同提出问题可以相容，参与不要求每项学生建议都采纳。合理课程拒绝属于具体教学安排，与框架自身GOV-02是否applied不同，不能把课程选择机械当框架写回状态，也不能以未采纳证明学生从未参与。[T-main]","个人资格用途不能仅靠群体分布检查替代个人依据及相称复核。教师专家判断也需一致性与不确定性说明，不能把“人工”当免检词。模型与人类判断都要放到实际用途的单位上检验。[T-main]","真实历史参照：OSR2021年3月2日报告评审2020成绩授予，36—37页记述历史校级成绩输入和聚合平等分析。50—52页记录学科、学校等层次检查、若干异常核验及双重编码，同时指出发布前个人层面人工复核有限。不能简化成完全没有检查。[P-OSR]","同报告57—58页指出申诉安排与范围，58页明确即使快速申诉，大学名额决定已依据初始成绩作出。这支持纠错与下游时间窗口错位问题，不证明所有纠错无法进入招生、无人恢复机会或全部损失均不可逆。[P-OSR]","所以重新发成绩不单独证明原机会和全部损失恢复；若资格更正及时进入录取条件，它可以构成真实下游改善，但还不能推出最终岗位或学位位置已经取得。新增可辨识点是更正到达哪个节点、在什么时间、实际改变何种条件。[T-main]","教学、家庭与组织支持需经过时间资源起作用。通知发出、账户激活、家长到会、行政出勤和知识增长不同。增加参与还可能增加翻译、照护维护劳动；要追承担者，不把行政活跃自动称学习提升。[T-main]","普通学习不因缺少G3条件历史残差而被否认。载体反馈介导学习和额外历史增量各按合同检验，不以G3当一切学习的门槛。原文培训例中取得新技能但当地无岗位，可以有真实学习且未就业。[T-main]","知识生产应追实际环节：议题、预算、评审、实践、成稿、发表、回报以及制作维修校勘翻译通信；不是所有研究都强套同一流程。只看已投稿论文会漏掉没资源成稿者，同数据再分析也不自动成为独立复现。[T-main]","专业能力、证照、决定权限与公众信任分别核。患者或实践者经验可以改变问题的重要性与提问方向，但不能独自证明总体因果。开放阅读、再用许可、贡献、共同定题和劳动承认也是不同入口，公开可读不等允许任何再用。[T-main]","缺公民观测记录可能是覆盖不足，不等当地对象不存在。表达和申诉不应以先学框架术语为前提。既有技能能否被看见与是否需要新训练不同；证书展示、招聘响应、岗位、工资、净岗位创造各有结果。累计创办、年度在办、规范名额和实际人数不能混算，未结业也不取消局部学习。[T-main]","连接§1.8、§6.3、十三部分、§15.3.3和§16.16，分别核框架用途、学习条件、知识表达、分析行动及具体教育场景。八入口为25.01教育目的与杜威等；25.02Freire等批判教育的问题设置；25.03文化资本隐性课程资格；25.04教师学生家庭环境协同；25.05大学与知识生产选择环节；25.06专家职业化公众知识；25.07共享公民科学开放各权限；25.08终身学习技能技术变化。未声称已完整阅读全部人物原作。[T-main]"],"argumentSteps":["明示教育目标及测量结果单位。","分通知参与出勤技能资格机会各证据。","个人决定核个人依据和相称复核，不只看分布。","更正逐节点追到达时间与实际条件变化。","记录未进入成稿或观测者及支持劳动，保留范围。"],"distinctions":[{"leftTitle":"技能形成","leftText":"实际知识能力改变。","rightTitle":"资格取得","rightText":"程序授予记录，不必等同技能全部。"},{"leftTitle":"聚合检查","leftText":"总体或分组结果。","rightTitle":"个人复核","rightText":"个人决定的证据与异常检查。"},{"leftTitle":"重新发成绩","leftText":"记录改正。","rightTitle":"机会恢复","rightText":"需下游及时承接及现实结果。"},{"leftTitle":"同数据再分析","leftText":"可改方法解释。","rightTitle":"独立复现","rightText":"独立性另有要求，不能自动命名。"}],"boundaries":["原文教学反例：培训有新技能而本地没有对应岗位。","原文边界：未结业不自动取消局部学习。","教学反例：同组两人分数交换后分布不变，个人决定仍改变。"],"questions":["均值相同能证明个人准确吗？","无就业证明无学习吗？","更正及时进入条件算改善吗？","没有G3就不算学习吗？"],"diagramPath":"/reading-assets/S-D-25/figures/d25-results.png","caseLinks":[{"title":"OSR对2020成绩授予模型的2021评审","href":"https://osr.statisticsauthority.gov.uk/wp-content/uploads/2021/03/Ensuring_statistical_models_command_public_confidence.pdf"}],"caseNotes":[{"title":"OSR对2020成绩授予模型的2021评审","text":"报告记录聚合平等和多层质量检查，同时指出发布前个人复核有限；58页说明大学名额决定已基于初始成绩作出。","sourceLabel":"Office for Statistics Regulation: Ensuring statistical models command public confidence","sourceUrl":"https://osr.statisticsauthority.gov.uk/wp-content/uploads/2021/03/Ensuring_statistical_models_command_public_confidence.pdf","sourceLocator":"2021-03-02报告，页36—37§3.2.2.3；50—52§3.3.3.3；57—58§3.4.2.3，页序与印刷一致","boundary":"不称毫无检查、所有申诉失败或机会全部不可恢复；只用指定7页的质量与时序事实。","href":"https://osr.statisticsauthority.gov.uk/wp-content/uploads/2021/03/Ensuring_statistical_models_command_public_confidence.pdf"}],"sourceRefs":[{"section":"D.25","start_line":4917,"end_line":4934,"startLine":4917,"endLine":4934}],"outputId":"section-d-25","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","teachingExamples":[{"title":"教学构造：分布不变、个人反转","text":"虚构甲乙真实分数90和50，被错记为50和90。组均值都70、分布仍{50,90}，但若纯教学录取门槛80，甲乙是否达线被反转。分布一致不能单独验证个人记录。","assumptions":"人工两人同测验，80为虚构门槛，忽略其他条件。","boundary":"不代表2020真实学生或证明全部模型错误。"},{"title":"教学构造：更正与窗口","text":"人工资格更正在第3日完成，招生锁定在第5日。若第4日接收并复核，更正可改变资格条件；若第6日才到达，需另查重开和补救程序。即使及时接收，也不能省略名额及最终决定证据。","assumptions":"虚构时点，不假定实际招生一律不可重开。","boundary":"时序不是完整权益判断，也不推所有迟到纠错无价值。"}],"counterexamples":[{"identity":"constructed_boundary","text":"原文教学反例：培训有新技能而本地没有对应岗位。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：未结业不自动取消局部学习。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"constructed_boundary","text":"教学反例：同组两人分数交换后分布不变，个人决定仍改变。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"均值相同能证明个人准确吗？","answer":"不能，90和50互换仍均值70。","basis":"用途单位。"},{"question":"无就业证明无学习吗？","answer":"不能，技能与岗位分别核。","basis":"不同结果。"},{"question":"更正及时进入条件算改善吗？","answer":"可以是真实下游改善，但不等最终位置取得。","basis":"保留局部。"},{"question":"没有G3就不算学习吗？","answer":"普通载体学习另按其合同检验，不由此否认。","basis":"模型范围。"}],"figures":[{"path":"/reading-assets/S-D-25/figures/d25-results.png","alt":"参与出勤技能资格与后续机会分开。","caption":"据D.25。"},{"path":"/reading-assets/S-D-25/figures/d25-scores.png","alt":"人工90/50互换均值70不变而80门槛资格反转。","caption":"教学构造。"},{"path":"/reading-assets/S-D-25/figures/d25-window.png","alt":"更正记录到下游接收复核及最终位置分开。","caption":"OSR历史时序问题，人工时间构造。"}],"diagramBrief":"三图分学习结果、个人与聚合检验及纠错时间窗。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"本单元涉及方法判断，真实来源仅支持所列事实；图与教学构造分别保留其身份。"},"openQuestions":["未跟踪每名学生的申诉、最终录取或损失。","未声称完整研究教育哲学及全部开放科学实践。"],"taskId":"S-D-25","sources":[{"id":"T-main","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§D.25，第4917—4934行","claim_support":["教育各结果、个人复核、普通学习、知识生产边界及八入口。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"P-OSR","title":"Office for Statistics Regulation: Ensuring statistical models command public confidence","url":"https://osr.statisticsauthority.gov.uk/wp-content/uploads/2021/03/Ensuring_statistical_models_command_public_confidence.pdf","source_type":"primary","version_or_date":"2021-03-02","locator":"2021-03-02报告，页36—37§3.2.2.3；50—52§3.3.3.3；57—58§3.4.2.3，页序与印刷一致","claim_support":["2020成绩模型使用历史校级成绩；聚合平等检查不等个体复核；存在若干质量检查但发布前个人人工复核有限；即使快速申诉，大学名额决定已基于初始成绩作出。"],"limits":["本人完整读指定7页，未声称通读76页；不称毫无人工检查，不推全部纠错失败或任何具体不可逆损失数量。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-25/lecture.md","sourcesPath":"/reading-assets/S-D-25/sources.json","sourceSlicePath":"/reading-assets/S-D-25/source/S-D-25.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-25/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-25.md","filePath":"theory/appendix-d/d-25.md"}'),d={name:"theory/appendix-d/d-25.md"};function l(p,e,u,m,_,f){const t=a("SectionLesson");return i(),n("div",null,[e[0]||(e[0]=o('<div class="theory-source"><h1 id="section-d-25" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.25</span><span class="xk-num__gap">　</span></span>教育、知识生产、专业与终身学习 <a class="header-anchor" href="#section-d-25" aria-label="Permalink to &quot;D.25　教育、知识生产、专业与终身学习 {#section-d-25}&quot;">​</a></h1><p>正文连接：§1.8；§6.3；§13；§15.3.3；§16.16。研究入口：25.01—25.08。</p><p>教育的目的、可进入的学习、实际知识技能、测验解释、资格授予与后续机会须分开。专业讲授与共同提出问题可以相容，学生参与不要求每个建议均获采纳；合理课程拒绝与框架自身GOV-02的applied状态属于不同层次。考试能够测量某种知识，也不因此证明机会公平。</p><p>个人资格用途中的群体分布检查，不能单独替代个人依据和相称复核；教师或专家判断也须说明一致性与不确定性（参见OSR，2021）。成绩记录更正之后，还须核对更正是否及时进入录取等下游决定；重新发放成绩不单独证明原有机会或全部损失已经恢复。</p><p>教学、家庭支持和组织环境经过具体的时间与资源起作用。通知发出、账户激活、家长到会、行政出勤改善与知识增长不同；参与还可能增加翻译、照护和维护劳动。普通人的学习不因缺少G3条件残差而被否认，载体型反馈介导学习与额外历史增量分别按自己的合同检验。</p><p>知识生产应按实际对象追踪相关环节，例如议题、预算、评审、实践、成稿、发表、回报，以及制作、维修、校勘、翻译与通信；不要求所有实践具有同一套关口。已投稿论文中的结果不能直接代表没有资源成稿的研究，同一数据的再分析也不是独立复现。专业能力、证照、决定权限和公众信任分别取证；患者或实践者的经验可以改变重要问题，却不单独证明总体因果效果。</p><p>教学例：培训者获得新技能，但当地没有相应岗位。不能因此说培训必然无学习，也不能以已结业承诺就业。开放阅读、再用许可、贡献、共同定题与劳动承认是不同入口；缺少公民观测记录可能是覆盖不足，不是当地对象不存在。表达和申诉不应以先掌握框架术语为条件。</p><p>既有技能或资格能否被看见，与是否需要新增训练是不同问题。证书展示、招聘响应、取得岗位、工资和净岗位创造各有结果；资格更正及时进入录取条件，可以构成真实的下游改善，却仍不等于最终位置已经取得。累计创办、年度在办、规范名额与实际学习人数不能混用，未结业也不自动取消局部学习。</p><p>专题定位：25.01 教育目的：杜威与其他教育哲学；25.02 批判教育：Freire 等；25.03 文化资本、隐性课程与资格；25.04 教师、学生、家庭与组织环境；25.05 大学、学术共同体与知识生产；25.06 专家、职业化与公众知识；25.07 知识共享、公民科学与开放实践；25.08 终身学习、技能形成与技术变化。</p></div>',1)),r(t,{section:"D.25"}),e[1]||(e[1]=c("div",{class:"theory-source"},null,-1))])}const T=s(d,[["render",l]]);export{h as __pageData,T as default};
